        "contact_page.canales_titulo": "CANALS DE CONTACTE",
        "contact_page.whatsapp_card_text": "Tens dubtes sobre els esdeveniments, les inscripcions o la normativa? Contacta directament amb nosaltres per WhatsApp.",
        "contact_page.community_card_title": "Comunitat de WhatsApp",
        "contact_page.community_card_text": "Uneix-te a la nostra comunitat de WhatsApp per rebre novetats, informació sobre propers esdeveniments i avisos de Mosco Events.",
        "contact_page.community_button": "UNIR-ME A LA COMUNITAT DE WHATSAPP",
